import SwiftUI

struct VigilHelpView:View {
    @Environment(\.dismiss) private var dismiss
    private let topics:[(String,String)]=[
        ("Focus sessions","Choose one task and a time, then press Start focus. Pause for a break or Finish when you're done. Your history shows the checks and ideas from each session."),
        ("The face","The Mac face follows your pointer. Hold Option and drag to move it; change its size in Settings. On a paired phone, the face keeps you company beside your screen. Prop the phone sideways below the monitor."),
        ("Pairing","On the Mac choose Pair. On your phone tap Pair and point the camera at the QR code. Keep both on the same Wi-Fi. Each edition has its own private pairing."),
        ("Hold to talk","Hold the face, say your task and release. Say ‘park this’ before an idea to save it for later. Speech recognition runs on your device. You can always type instead."),
        ("Nudges","During a focus session, repeated clear signs of drift can bring a kind reminder. Ambiguous or protected screens do not count as drift. Test a nudge from the Mac menu."),
        ("The parking lot","Type an idea and press Park, or say ‘park this’ followed by the idea. Open Parking lot to revisit it. Parking an idea leaves your current task in place."),
        ("Calendar","Choose Use today's calendar and allow access to read your events. Pick an event as your task. Vigil never changes your calendar. The Mac can give a ten-minute meeting reminder."),
        ("Models and status dots","Settings lists each model. Green means its latest check answered; amber means waiting or limited; red means unavailable. Test all now repeats eligible checks. Checks run at launch and every 30 minutes. Vigil tries available models in speed order and moves on after an error or timeout. Limited models rest until their retry time. Only vision models see screen checks. If remote models fail, on-device help keeps the session going."),
        ("Privacy","Your tasks, ideas and history are saved on your own devices. Pairing is encrypted. Wake-word and speech recognition stay on-device. Natural speech is generated by Vigil’s secure brain and can be cached privately for playback. Protected work windows skip the whole screen check. Eligible checks send your task, app name, recognized screen text and image briefly to a model. Vigil never saves the image. Model providers have their own data-use and retention policies. Inference prompts and images are not logged. Generated speech has a small private playback cache. Macy's edition has separate data and per-device access; provider keys are never bundled or paired."),
        ("iPhone not pairing","Open Vigil on both devices, keep them on the same Wi-Fi and scan a fresh Mac code. In your device's Settings allow Vigil access to Local Network and Camera. A sleeping Mac or a Wi-Fi network that separates devices can prevent pairing."),
        ("No AI answers","Open Settings and press Test all now. Amber models may be waiting for a usage reset; red models may have a connection or credential problem. Check your internet connection. Your timer, parking lot and local fallback keep working. TestFlight editions connect automatically; no provider key is needed."),
        ("Permissions","For reminders, allow Notifications. For voice, allow Microphone and Speech Recognition. For pairing, allow Local Network and Camera on the phone. For calendar, allow Calendar access. On the Mac allow Screen Recording only if you want screen checks. If you declined, change the permission in the device's Settings, then reopen Vigil.")
    ]
    private var featureTopics:[(String,String)] {
        #if VIGIL_VOICE_VISION
        return [
            ("Settings and Try everything", "Use the Vigil eye in the menu bar → Settings, right-click the desktop face → Settings, or press Command-comma while Vigil is active. Try everything has a separate button for every feature and Sound check. What is this gives three seconds to put the pointer over the item. Reminder and meeting tests are labeled previews and do not alter your data."),
            ("Five nudge styles","Settings → Nudges, voice and vision lets you select Chime, Bounce, Color glow, Eye wiggle or Spoken line. Each has its own Test button. Quiet nudges remain silent. Reduce Motion replaces moving effects with a glow."),
            ("Spoken nudges and answers","Macy’s natural US English speech runs on Vigil’s secure server and is cached for fast playback. No API keys or account setup. Audio follows your device’s current sound output. Preview lets you hear it. Wake words and speech recognition stay on-device. If the server is unavailable, cached speech can still play; new answers remain visible as text."),
            ("Vigil, what is this?","On Mac, enable wake listening, put your pointer over an item and say ‘Vigil, what is this?’ Accessibility text is preferred; otherwise only a small crop is sent. Protected work windows and secure fields are skipped. iPhone and iPad cannot read another app or the Mac pointer."),
            ("Answer sparkles and haptics","An answer appears in a small face bubble with a brief sparkle and a light haptic tap where the hardware supports it. Spoken answers respect your voice switch and volume."),
            ("Vigil, look at me","Ask explicitly, then speak your question during the four-second video and audio clip. Recording has a visible red indicator and Cancel button. The camera stops before inference. Three small frames plus on-device transcribed words go to free non-OpenAI models; raw video and audio are not uploaded. The temporary clip is removed after the answer, error or cancellation. Keeping requested clips is off unless you enable it in Settings."),
            ("Next small step", "Say or type ‘Vigil, I’m stuck’, or press I’m stuck. Vigil uses your declared task, without capturing your screen. Free non-OpenAI models fail over; if none answers, a simple local next step still works. Toggle Next-step help in Settings."),
            ("Voice reminders", "Say or type ‘Vigil, remind me in 15 minutes to stretch’. One to 1,440 minutes are supported. Due reminders speak and nudge while Vigil runs. Apple notifications cover a closed/backgrounded app; automatic spoken delivery is not possible while iOS suspends Vigil. Settings lists reminders and Cancel. Turning reminders off cancels pending alerts. The global voice switch and volume are respected."),
            ("Five-minute meeting warning", "Turn on meeting warnings in Settings. Calendar permission is requested only if not already decided. Declining it never causes repeat prompts. Vigil checks for changed or canceled events, skips all-day and declined events and speaks ‘Meeting in 5 minutes’ with the title. Calendar checks stay local; the spoken sentence goes to Vigil’s brain to generate speech. Warnings require Vigil running."),
            ("Break nudge", "After a configurable interval (50 minutes by default), Vigil says ‘Stand up. Drink water.’ The Mac uses idle time to reset after a five-minute absence; sleep and lock reset it too. On iPhone/iPad, it counts time with Vigil active. This estimates work time, not physical sitting. Use I took a break to reset it. The old session milestone nudge is replaced in this edition to avoid duplicates."),
            ("Tired check and camera cover", "Off by default. Enable Tired check, then confirm Camera cover is open for this run. There is no reliable physical-cover sensor: close the control when closing the cover. Every five minutes Apple Vision checks one in-memory frame for eye/mouth proportions and posture. Dark/covered frames are skipped. No recording, microphone, stored image, upload or remote model is used. Checks pause on lock, sleep, backgrounding or requested video recording. Turning either switch off cancels capture immediately. Speech and a face bubble suggest a break only after repeated cues; this is fallible and does not diagnose tiredness."),
            ("Voice and vision permissions","The feature introduction explains Microphone, Speech Recognition, Accessibility and Screen Recording before requesting access. Camera is requested only for an explicit recording or enabled tired check with an open-cover confirmation. Permission refusal is respected; use system Settings to change it. Wake listening stays on-device and requires on-device English recognition. It runs while Vigil is open on iPhone/iPad and stops when backgrounded. Use Stop listening any time. If an Apple recognition session stops, use Restart listening in Settings.")
        ]
        #else
        return []
        #endif
    }
    var body:some View {
        ScrollView { VStack(alignment:.leading,spacing:20){
            HStack{Text("Vigil Help").font(.largeTitle.weight(.semibold));Spacer();Button("Done"){dismiss()}}
            Text("A little company for the task ahead.").foregroundStyle(.secondary)
            ForEach(topics.indices,id:\.self){i in VStack(alignment:.leading,spacing:7){Text(topics[i].0).font(.headline);Text(topics[i].1).fixedSize(horizontal:false,vertical:true).foregroundStyle(.secondary)}}
            ForEach(featureTopics.indices,id:\.self){i in VStack(alignment:.leading,spacing:7){Text(featureTopics[i].0).font(.headline);Text(featureTopics[i].1).fixedSize(horizontal:false,vertical:true).foregroundStyle(.secondary)}}
            Link("Report a problem",destination:VigilSupport.reportURL)
        }.padding(24).frame(maxWidth:680,alignment:.leading).frame(maxWidth:.infinity,alignment:.center)}.frame(minWidth:300,minHeight:300)
    }
}
enum VigilSupport {
    static var version:String {"Vigil \(Bundle.main.object(forInfoDictionaryKey:"CFBundleShortVersionString") as? String ?? "1.0") (\(Bundle.main.object(forInfoDictionaryKey:"CFBundleVersion") as? String ?? "4"))"}
    static var reportURL:URL {
        var parts=URLComponents();parts.scheme="mailto";parts.path="contact@kafworlddigital.com"
        parts.queryItems=[URLQueryItem(name:"subject",value:"Vigil problem · "+version),URLQueryItem(name:"body",value:"What happened?\n\nDevice: "+ProcessInfo.processInfo.operatingSystemVersionString+"\nVersion: "+version+"\n\nPlease check this message before sending. Don't include keys or private screen content.")]
        return parts.url!
    }
}
